// Build an insightful error report from the n8n Error Trigger.
const t = $('Error Trigger').first().json || {};
const ex = t.execution || {};
const wf = t.workflow || {};
const err = ex.error || {};
const phone = ($json && $json.phone_number) || '';

const failedNode = (err.node && err.node.name) || ex.lastNodeExecuted || 'unknown';
const httpCode = err.httpCode || err.statusCode || (err.context && err.context.httpCode) || '';
const message = err.message || (typeof err === 'string' ? err : '') || 'Unknown error';
const description = err.description || (err.context && err.context.description) || '';
const stack = String(err.stack || '').split('\n').slice(0, 8).join('\n');
const when = new Date().toLocaleString('ro-RO', { timeZone: 'Europe/Bucharest' });
const execUrl = ex.url || '';

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const subject = '⚠️ ' + (wf.name || 'Workflow') + ' — failed at "' + failedNode + '"' + (httpCode ? ' (' + httpCode + ')' : '');

const fields = [
  ['Workflow', (wf.name || '?') + ' (' + (wf.id || '?') + ')'],
  ['Failed node', failedNode],
  ['Error', message],
  description ? ['Details', description] : null,
  httpCode ? ['HTTP code', String(httpCode)] : null,
  ['When', when + ' (Europe/Bucharest)'],
  ['Execution ID', String(ex.id || '?')],
  ex.mode ? ['Mode', ex.mode] : null,
  phone ? ['Affected user (phone)', phone] : null,
].filter(Boolean);

const table = fields
  .map((r) => '<tr><td style="padding:4px 12px;font-weight:600;vertical-align:top;white-space:nowrap">' + esc(r[0]) + '</td><td style="padding:4px 12px">' + esc(r[1]) + '</td></tr>')
  .join('');

const html =
  '<div style="font-family:system-ui,Segoe UI,Arial,sans-serif;font-size:14px;color:#111;line-height:1.45">' +
  '<h2 style="margin:0 0 10px">' + esc(wf.name || 'Workflow') + ' error</h2>' +
  '<table style="border-collapse:collapse;background:#f7f7f8;border:1px solid #e2e2e2">' + table + '</table>' +
  (execUrl ? '<p style="margin:14px 0"><a href="' + esc(execUrl) + '" style="color:#2563eb">Open the failed execution in n8n →</a></p>' : '') +
  '<p style="margin:14px 0 4px;color:#666;font-size:12px">Stack trace (top frames):</p>' +
  '<pre style="background:#111;color:#eee;padding:10px;border-radius:6px;overflow:auto;font-size:12px;white-space:pre-wrap">' + esc(stack) + '</pre>' +
  '</div>';

return [{ json: { subject, html, phone } }];
